import { hemisphereOf } from "@/lib/time/season";

// The weather picture in its season: rain in autumn is russet trees and leaves
// on a wet lane, in summer it's a shower over wildflowers. Keys must match the
// files generated by scripts/generate-watercolors.mjs (public/watercolor/*.webp);
// anything without a seasonal version keeps its all-year picture.

export type Season = "spring" | "summer" | "autumn" | "winter";

const SKY_CONDITIONS = ["clear", "cloud", "overcast", "fog", "rain", "storm", "sunrise", "sunset", "twilight", "night"];
const SEASONS: Season[] = ["spring", "summer", "autumn", "winter"];

export const SEASONAL_SKIES: ReadonlySet<string> = new Set([
  ...SKY_CONDITIONS.flatMap((c) => SEASONS.map((s) => `${c}-${s}`)),
  "snow-autumn", "snow-winter", "snow-spring",
]);

/** Meteorological seasons (Mar–May spring, …), flipped for the southern hemisphere. */
export function fourSeason(date: Date, latitude: number): Season {
  const month = date.getUTCMonth() + 1;
  const north: Season = month >= 3 && month <= 5 ? "spring" : month >= 6 && month <= 8 ? "summer" : month >= 9 && month <= 11 ? "autumn" : "winter";
  if (hemisphereOf(latitude) === "north") return north;
  return ({ spring: "autumn", summer: "winter", autumn: "spring", winter: "summer" } as const)[north];
}

export function seasonalSkyKey(key: string, date: Date, latitude: number): string {
  const seasonal = `${key}-${fourSeason(date, latitude)}`;
  return SEASONAL_SKIES.has(seasonal) ? seasonal : key;
}
